const REPORT_API='http://127.0.0.1:5174/api/report';
async function fetchReportPdf(kind,payload){const res=await fetch(`${REPORT_API}/${kind}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!res.ok)throw new Error('The report API returned an unexpected response. Confirm that npm run server is running on port 5174.');return res.blob()}
function triggerDownload(blob,filename){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
async function downloadReportPair(payload,baseName){const [full,summary]=await Promise.all([fetchReportPdf('pdf',payload),fetchReportPdf('summary-pdf',payload)]);triggerDownload(full,`${baseName}-report.pdf`);triggerDownload(summary,`${baseName}-summary.pdf`)}
function runToReportPayload(run){return {application:run.application,title:`${run.application} Security Assessment`,assessmentId:run.assessmentId,generatedAt:run.endTime,scope:run.scope,filesAnalyzed:run.filesAnalyzed,rulesExecuted:run.rulesExecuted,summary:`${run.filesAnalyzed} files analyzed using ${run.rulesExecuted.length} focused rules. ${run.findings.length} findings were generated from the uploaded source archive.`,findings:run.findings.map(f=>({id:f.id,title:f.title,status:f.status,severity:f.severity,confidence:f.confidence,file:f.file,line:f.line,description:f.description,evidence:f.evidence,controls:f.securityControls||f.controls||[],recommendation:f.recommendation}))}}

