const stages=['Initializing assessment','Mapping application','Discovering endpoints','Classifying components','Analyzing authentication','Analyzing authorization','Assessing APIs','Checking security controls','Correlating findings','Calculating risk','Generating evidence','Assessment complete'];
function reducer(s,a){switch(a.type){
 case 'SELECT_FINDING': return {...s,selectedFinding:a.id,returnPage:a.returnTo||'findings'}; case 'SELECT_ASSET': return {...s,selectedAsset:a.id}; case 'SELECT_SOURCE':return {...s,selectedSource:a.file};
 case 'LOAD_RUN': {const r=a.run, assets=[...new Set(r.findings.map(f=>f.affectedAsset))].map((name,i)=>({id:`AST-${String(i+1).padStart(3,'0')}`,name,type:'Assessed source component',domain:'Static analysis',importance:'Contextual',endpoints:[],controls:[]}));const byFile=Object.fromEntries(assets.map(x=>[x.name,x.id]));return {...s,app:{...s.app,id:r.assessmentId,name:r.application,environment:'LOCAL / ISOLATED ANALYSIS',scope:r.scope,lastRun:new Date(r.endTime).toLocaleString()},assets,findings:r.findings.map(f=>({...f,asset:byFile[f.affectedAsset],files:[f.file],flow:['Source file',`Line ${f.line}`,f.ruleId,'Static-analysis evidence'],controls:f.securityControls,final:f.status==='NOT CONFIRMED'?'Controls identified in the inspected source context; signal not confirmed.':'Potential finding requires security review.'})),paths:[],assessment:{running:false,stage:11,completed:true},selectedFinding:r.findings[0]?.id||null,run:r,activities:[{id:r.assessmentId,application:r.application,timestamp:r.endTime,filesAnalyzed:r.filesAnalyzed,findingsCount:r.findings.length,run:r},...s.activities]};}
 case 'REMEDIATE': return {...s,findings:s.findings.map(f=>f.id===a.id?{...f,status:'remediated',verified:'Pending retest'}:f),paths:s.paths.map(p=>p.finding===a.id?{...p,status:'mitigated'}:p)};
 case 'RETEST': return {...s,findings:s.findings.map(f=>f.id===a.id?{...f,status:'verified',verified:'Today, 11:08 IST'}:f),paths:s.paths.map(p=>p.finding===a.id?{...p,status:'verified'}:p)};
 case 'SIMULATE':return {...s,simulation:{finding:a.id,mode:a.mode}}; case 'CLEAR_SIM':return {...s,simulation:{finding:null,mode:null}};
 case 'ASSESS':return {...s,assessment:{running:true,stage:0,completed:false}}; case 'STAGE':return {...s,assessment:{...s.assessment,stage:a.stage, running:a.stage<stages.length-1,completed:a.stage===stages.length-1}};
 case 'TOAST':return {...s,toast:{id:Date.now(),message:a.message,tone:a.tone||'safe'}}; case 'CLEAR_TOAST':return {...s,toast:null};
 default:return s}}
const Store=createContext(); function useStore(){return useContext(Store)}
