function calc(s){const signals=s.findings.length;const count=x=>s.findings.filter(f=>f.severity===x).length;const confirmed=s.findings.filter(f=>f.status==='confirmed').length;const notConfirmed=s.findings.filter(f=>f.status==='not-confirmed').length; return {active:[],count,verified:notConfirmed,confirmed,notConfirmed,signals,score:92,paths:s.paths.filter(p=>p.status==='active').length, progress:100}}
function Badge({children,type}){return <span className={`badge ${type||String(children).toLowerCase().replace(' ','-')}`}>{children}</span>}
function AnimatedNumber({value,duration=700}){const target=typeof value==='number'?value:parseFloat(value);const finite=Number.isFinite(target);const [display,setDisplay]=useState(finite?0:value);useEffect(()=>{if(!finite){setDisplay(value);return}let raf,start;const step=t=>{if(!start)start=t;const p=Math.min(1,(t-start)/duration);setDisplay(Math.round(target*(1-Math.pow(1-p,3))));if(p<1)raf=requestAnimationFrame(step)};raf=requestAnimationFrame(step);return ()=>cancelAnimationFrame(raf)},[target,finite,duration]);return <>{display}</>}
function Toast(){const {state,dispatch}=useStore();useEffect(()=>{if(!state.toast)return;const t=setTimeout(()=>dispatch({type:'CLEAR_TOAST'}),3000);return ()=>clearTimeout(t)},[state.toast,dispatch]);if(!state.toast)return null;return <div className={`toast ${state.toast.tone}`} key={state.toast.id}><span>{state.toast.message}</span><button onClick={()=>dispatch({type:'CLEAR_TOAST'})}>✕</button></div>}
function Stat({label,value,sub,accent}){return <div className="stat"><span>{label}</span><strong className={accent}><AnimatedNumber value={value}/></strong><small>{sub}</small></div>}
function ThemeToggle(){const [theme,setTheme]=useState(()=>localStorage.getItem('sentry-theme')||'dark');const light=theme==='light';useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('sentry-theme',theme)},[theme]);return <button className="theme-toggle" onClick={()=>setTheme(light?'dark':'light')} aria-label={`Switch to ${light?'dark':'light'} mode`} title={`Switch to ${light?'dark':'light'} mode`}><span aria-hidden="true">{light?'☾':'☀'}</span><b>{light?'Dark':'Light'}</b></button>}
