function ComplianceReport(){return <Page title="Compliance & Ethics Report" desc="Scope boundaries and evidence handling for this local prototype assessment."><section className="compliance-banner"><Shield size={22}/><div><b>Authorized source review · isolated demo</b><span>All interactive threat records on this screen are synthetic. No live production system is contacted.</span></div></section><div className="compliance-grid"><article className="panel compliance-card"><span className="compliance-icon green"><Shield size={18}/></span><span className="eyebrow">PRODUCTION BOUNDARY</span><h3>Zero live interaction</h3><p>The prototype does not send scans or test payloads to worldmonitor.app. The external link is informational only.</p><b className="compliance-state">ENFORCED BY LOCAL DEMO DESIGN</b></article><article className="panel compliance-card"><span className="compliance-icon purple"><Box size={18}/></span><span className="eyebrow">DIGITAL TWIN</span><h3>Sandbox flow is simulated</h3><p>Isolation screens demonstrate the intended ephemeral namespace lifecycle using local presentation state.</p><b className="compliance-state">NO VCLUSTER PROVISIONED</b></article><article className="panel compliance-card"><span className="compliance-icon cyan"><Activity size={18}/></span><span className="eyebrow">DATA PROVENANCE</span><h3>Synthetic demo records</h3><p>Telemetry, evidence, and attack narratives are presentation fixtures and do not describe observed production activity.</p><b className="compliance-state">SYNTHETIC DATA</b></article><article className="panel compliance-card"><span className="compliance-icon amber"><FileCheck2 size={18}/></span><span className="eyebrow">TRACEABILITY</span><h3>Assessment context visible</h3><p>Target, authorization context, and isolation status remain visible in the persistent workspace header.</p><b className="compliance-state">SCOPE DISCLOSED</b></article></div><section className="panel ethics-scope"><span className="eyebrow">OPERATING PRINCIPLES</span><h3>What this prototype demonstrates</h3><ul><li>Source archive review is a user-triggered, local assessment workflow.</li><li>Telemetry and exploit scenarios use synthetic fixtures and remain user-triggered.</li><li>Sandbox evidence is demonstrative; it is not a captured production artifact.</li><li>Remediation actions are UI demonstrations and do not submit changes to GitHub.</li></ul></section></Page>}
function FindingsTable({findings,setPage}){const {state,dispatch}=useStore();const asset=id=>state.assets.find(a=>a.id===id);return <div className="table-wrap"><table><thead><tr><th>ID / finding</th><th>Severity</th><th>Confidence</th><th>Affected asset</th><th>Status</th><th></th></tr></thead><tbody>{findings.map(f=><tr key={f.id}><td><b>{f.id}</b><span>{f.title}</span></td><td><Badge type={f.severity}>{f.severity}</Badge></td><td><div className="confidence"><i style={{width:`${f.confidence}%`}}/>{f.confidence}%</div></td><td>{asset(f.asset)?.name}</td><td><Badge type={f.status}>{f.status}</Badge></td><td><button className="icon-btn" onClick={()=>{dispatch({type:'SELECT_FINDING',id:f.id});setPage('detail')}}>→</button></td></tr>)}</tbody></table></div>}
function Page({title,desc,children,action}){return <main><div className="title"><div><span className="eyebrow">SECURITY INTELLIGENCE</span><h1>{title}</h1><p>{desc}</p></div>{action}</div>{children}</main>}
function Findings({setPage}){const {state}=useStore();return <Page title="Vulnerability findings" desc="Prioritized World Monitor security findings across feeds, APIs, AI processing, and infrastructure." action={<Badge type="info">SIMULATED ASSESSMENT PROFILE</Badge>}><section className="panel">{state.findings.length?<FindingsTable findings={state.findings} setPage={setPage}/>:<div className="empty-state"><h3>No repository findings loaded</h3><p>Upload a source archive to run the static analysis workflow. Synthetic telemetry demos are shown separately and are not counted as code findings.</p><button className="primary" onClick={()=>setPage('assessment')}>Start source assessment</button></div>}</section></Page>}
function Detail({setPage}){const {state,dispatch}=useStore();const f=state.findings.find(x=>x.id===state.selectedFinding)||state.findings[0];if(!f)return <Page title="No finding selected" desc="Run an assessment or select an investigation from the findings page."/>;const a=state.assets.find(x=>x.id===f.asset)||{name:f.affectedAsset||'Source file'},path=state.paths.find(p=>p.id===f.path),isProtected=f.status==='NOT CONFIRMED',back=state.returnPage||'findings';return <Page title={f.title} desc={`${f.id} · ${f.category} · ${a.name}`} action={<button className="ghost" onClick={()=>setPage(back)}>← {back==='graph'?'Back to knowledge graph':'All investigations'}</button>}><div className="detail-head"><Badge type="info">RULE: {f.ruleId}</Badge><div><b>Assessment Confidence</b><strong>{f.confidence}%</strong></div><Badge type={isProtected?'safe':'medium'}>{f.status}</Badge></div><div className="detail-grid"><section className="panel"><span className="eyebrow">SOURCE ANALYSIS SIGNAL</span><h3>{f.description}</h3><p className="readable">This result was generated from the uploaded source archive. It requires review unless relevant controls support a not-confirmed assessment.</p><div className="investigation"><span>ANALYSIS EVIDENCE</span><i>↓</i><b>{f.file} · line {f.line}</b><i>↓</i><b>{f.ruleId}</b><i>↓</i><strong>STATUS: {f.status}</strong></div><h3>Source-code evidence</h3><p className="muted">SOURCE CODE EVIDENCE · actual matching lines and surrounding context</p><div className="source-links">{(f.files||[f.file]).map(file=><button key={file} onClick={()=>{dispatch({type:'SELECT_SOURCE',file});setPage('source')}}>⌘ {file} <span>Open at line {f.line} →</span></button>)}</div><h3>Validation performed</h3>{[f.reason,...(f.securityControls||f.controls||[])].map(e=><div className="evidence" key={e}><i>✓</i>{e}</div>)}</section><section className="side-stack"><section className="panel"><h3>Security controls found</h3><p className="muted">ASSESSMENT INTERPRETATION · controls considered near the matched code</p>{(f.securityControls||f.controls||[]).length?(f.securityControls||f.controls||[]).map(c=><div className="factor" key={c}><span>{c}</span><b className="safe-text">Detected</b></div>):<p className="readable">No strong control was identified in the inspected local context.</p>}</section><section className="panel"><h3>Explainable assessment</h3><p className="muted">Prototype Risk Model · static-analysis confidence, not an industry-standard probability.</p>{[['Severity',f.severity],['Rule confidence',`${f.confidence}%`],['Affected file',f.file],['Location',`Line ${f.line}`]].map(x=><div className="factor" key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}<p className="risk-note">{f.recommendation}</p></section><section className="panel"><h3>Final assessment</h3><p className="readable">{f.final}</p><button className="ghost" onClick={()=>{dispatch({type:'SIMULATE',id:f.id,mode:'exploit'});setPage('simulation')}}>Model potential impact</button></section>{path&&<section className="panel link-card" onClick={()=>setPage('paths')}><span>RELATED CONTROL FLOW</span><b>{path.id} · {path.name}</b> <em>View flow →</em></section>}</section></div></Page>}
function Map({setPage}){const {state,dispatch}=useStore();const [asset,setAsset]=useState(state.selectedAsset||'AST-003');const a=state.assets.find(x=>x.id===asset)||state.assets[0];return <Page title="Application map" desc="Application assets and their assessment context."><div className="map-layout"><section className="panel tree"><div className="root-node">◈ World Monitor <small>WM-SEC-2026-001</small></div>{state.assets.map(x=><button className={asset===x.id?'tree-node selected':''||'tree-node'} key={x.id} onClick={()=>{setAsset(x.id);dispatch({type:'SELECT_ASSET',id:x.id})}}><i>└</i>{x.name}<span>{x.type}</span></button>)}</section><section className="panel asset"><span className="eyebrow">{a.type} · {a.id}</span><h2>{a.name}</h2><div className="asset-meta"><div><span>SECURITY IMPORTANCE</span><b>{a.importance}</b></div><div><span>ASSESSMENT CONTEXT</span><b>{a.domain}</b></div></div><h3>Related endpoints</h3>{a.endpoints.map(e=><code key={e}>{e}</code>)}<h3>Security controls</h3><div className="chips">{a.controls.map(c=><Badge type="info" key={c}>{c}</Badge>)}</div><h3>Related findings</h3>{state.findings.filter(f=>f.asset===a.id).length?state.findings.filter(f=>f.asset===a.id).map(f=><button className="related" key={f.id} onClick={()=>{dispatch({type:'SELECT_FINDING',id:f.id});setPage('detail')}}><Badge type={f.severity}>{f.id}</Badge>{f.title} →</button>):<p className="muted">No assessment findings for this panel.</p>}</section></div></Page>}
function Graph({setPage}){const {state}=useStore();return <Page title="Security knowledge graph" desc="Explore how application assets, findings, and attack paths connect."><section className="graph-shell"><div className="graph-toolbar"><div><span className="eyebrow">APPLICATION SECURITY MODEL</span><h3>{state.assets.length} assets · {state.findings.length} findings · {state.paths.length} paths</h3></div><button className="text" onClick={()=>setPage('findings')}>Review findings →</button></div><div className="module-grid" style={{padding:16}}>{state.assets.map(asset=><article key={asset.id} className="panel"><span className="eyebrow">{asset.type} · {asset.importance}</span><h3 style={{margin:'8px 0'}}>{asset.name}</h3><p className="muted">{asset.domain}</p>{state.findings.filter(f=>f.asset===asset.id).map(f=><button className="related" key={f.id} onClick={()=>setPage('detail')}><Badge type={f.severity}>{f.id}</Badge>{f.title} →</button>)}</article>)}</div><div className="graph-footnote"><i>●</i> Application relationships and assessment results are shown from the current local Sentry workspace.</div></section></Page>}
function GraphCard({kind,label,title,sub}){return <div className={`flow-card ${kind}`}><small>{label}</small><b>{title}</b><span>{sub}</span></div>}
function FlowLink({text}){return <div className="flow-link"><span>{text}</span><i>→</i></div>}
function GraphNode({x,y,label,title,type}){return <button className={'g-node '+type} style={{left:x,top:y}}><small>{label}</small><b>{title}</b></button>}
function Paths(){const {state,dispatch,setPage}=useStore();const path=state.paths.find(x=>x.id==='AP-001')||seed.paths[0];return <Page title="Attack paths" desc="Prioritized exposure chains across the World Monitor application graph."><section className="panel path"><div className="panel-head"><div><span className="eyebrow">SIMULATED ASSESSMENT · PATH {path.id}</span><h3>External Feed → AIS Ship Tracking Relay → Input Validation Weakness → SSRF → Redis Cache → Internal Service Access</h3><p>{path.detectionSource} · Affected asset: {path.affectedAsset}</p></div><Badge type="high">HIGH · RISK {path.riskScore}/100</Badge></div><div className="path-nodes">{path.nodes.map((node,i)=><React.Fragment key={node}>{i>0&&<i>→</i>}<button onClick={()=>{const target=state.assets.find(a=>a.name===node);if(target){dispatch({type:'SELECT_ASSET',id:target.id});setPage('map')}}}>{node}</button></React.Fragment>)}</div><div className="path-foot"><span>Status <b>{path.status}</b></span><span>Affected asset <b>{path.affectedAsset}</b></span><span>Detection source <b>{path.detectionSource}</b></span></div><div className="detail-grid"><section className="panel"><span className="eyebrow">TECHNICAL EXPLANATION</span><p className="readable">{path.explanation}</p></section><section className="panel"><span className="eyebrow">RECOMMENDED REMEDIATION</span><p className="readable">{path.recommendation}</p><button className="text" onClick={()=>setPage('remediation-workspace')}>Open remediation workspace →</button></section></div><p className="muted">Scenario data is simulated for the assessment demonstration and is not represented as a verified production exploit.</p></section></Page>}
function Simulation(){const {state,dispatch}=useStore();const [fId,setF]=useState(state.simulation.finding||'F-001');const f=state.findings.find(x=>x.id===fId), sim=state.simulation;return <Page title="What-if security simulation" desc="Model an initial security signal without changing the source-review assessment."><div className="simulation-banner">SIMULATION — NO PRODUCTION ACTION · DOES NOT CHANGE FINAL ASSESSMENT</div><div className="two"><section className="panel"><h3>Scenario target</h3><select value={fId} onChange={e=>setF(e.target.value)}>{state.findings.map(f=><option value={f.id} key={f.id}>{f.id} · {f.title}</option>)}</select><div className="scenario-actions"><button className="primary" onClick={()=>dispatch({type:'SIMULATE',id:fId,mode:'exploit'})}>Model initial concern</button><button className="ghost" onClick={()=>dispatch({type:'SIMULATE',id:fId,mode:'remediate'})}>Model control absence</button></div><h3>Final assessed risk</h3><div className="big-risk">INFORMATIONAL <small>Signal confidence {f.confidence}%</small></div></section><section className="panel sim-result">{!sim.mode?<><h3>Ready to model</h3><p>Select a hypothetical scenario to visualize why the initial signal warranted investigation.</p></>:sim.mode==='exploit'?<><Badge type="info">HYPOTHETICAL SIGNAL</Badge><h2>Potential impact before validation</h2><p>This models the concern before the inspected controls were considered. It is not an executed action or a confirmed vulnerability.</p><div className="impact">Final assessment <b>NOT CONFIRMED</b></div></>:<><Badge type="safe">CONTROL ABSENCE MODEL</Badge><h2>Why the control matters</h2><p>Without the traced validation control, the initial signal would require further validation. The inspected implementation includes the control.</p><div className="impact">Final assessment <b>CONTROLS VALIDATED</b></div></>}<button className="text" onClick={()=>dispatch({type:'CLEAR_SIM'})}>Clear simulation</button></section></div></Page>}
function Remediation({setPage}){const {state,dispatch}=useStore(),m=calc(state);return <Page title="Control validation center" desc="Remediation actions are available after an uploaded source archive produces findings."><div className="grid mini-metrics"><Stat label="Controls validated" value={m.notConfirmed} sub="No source findings loaded" accent="safe"/><Stat label="Remediation required" value="0" sub="No source findings loaded" accent="safe"/><Stat label="Follow-up posture" value="Monitor" sub="Maintain validated controls" accent="blue"/></div>{state.findings.map(f=><section className="panel remediation" key={f.id}><div><Badge type="info">{f.id}</Badge><h3>{f.title}</h3><p>{f.recommendation}</p></div><div><Badge type="safe">SOURCE REVIEW REQUIRED</Badge><button className="ghost" onClick={()=>{dispatch({type:'SELECT_FINDING',id:f.id});setPage('detail')}}>Inspect evidence</button></div></section>)}</Page>}
function Verification(){const {state}=useStore(),m=calc(state);return <Page title="Verification & retesting" desc="Verification records are created after an actual source assessment and retest."><section className="panel verification"><div><span className="eyebrow">INITIAL REVIEW</span><h2>Source findings <Badge type="info">{m.signals} LOADED</Badge></h2><p>No finding records are loaded before an assessment run.</p></div><div className="arrow">→</div><div><span className="eyebrow">FINAL ASSESSMENT</span><h2>Retest results <Badge type="safe">{m.notConfirmed} AVAILABLE</Badge></h2><p>Run an assessment and retest to populate verification records.</p></div></section><section className="panel"><h3>Verification record</h3>{state.findings.map(f=><div className="verify-row" key={f.id}><span>{f.id} · {f.category}</span><Badge type="safe">Controls validated</Badge></div>)}</section></Page>}
function Assessment(){const {state,dispatch}=useStore();const [file,setFile]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async()=>{if(!file){setError('Select a source-code ZIP archive first.');return}setBusy(true);setError('');try{const data=new FormData();data.append('source',file);data.append('application',file.name.replace(/\.zip$/i,''));const res=await fetch('http://127.0.0.1:5174/api/assess',{method:'POST',body:data});const type=res.headers.get('content-type')||'';const body=type.includes('application/json')?await res.json():{error:'The assessment API returned an unexpected response. Confirm that npm run server is running on port 5174.'};if(!res.ok)throw new Error(body.error||'Assessment failed');dispatch({type:'LOAD_RUN',run:body});dispatch({type:'TOAST',message:`Assessment complete · ${body.findings.length} findings generated`})}catch(e){setError(e.message)}finally{setBusy(false)}};const download=async()=>{const r=state.run;if(!r)return;try{await downloadReportPair(runToReportPayload(r),`${r.application}-${r.assessmentId}`);dispatch({type:'TOAST',message:'Report downloaded'})}catch(e){setError(e.message)}};return <Page title="Security assessment" desc="Upload a source archive for isolated, non-executing static security analysis." action={<Badge type="safe">AUTHORIZED SOURCE REVIEW</Badge>}><section className="panel assessment"><div className="assessment-top"><div><h3>Assessment input</h3><p>ZIP archives are treated as untrusted data. Source is inspected; it is never executed.</p></div>{state.run&&<button className="ghost report-download" onClick={download}>↓ Download analysis report</button>}</div><div className="upload-box"><input id="source-zip" type="file" accept=".zip,application/zip" onChange={e=>{setFile(e.target.files?.[0]||null);setError('')}}/><label htmlFor="source-zip"><b>{file?file.name:'worldmonitor-source-v1.2.zip'}</b><span>{file?`${Math.ceil(file.size/1024)} KB selected · ready for analysis`:'Demo assessment profile loaded · choose a ZIP to run a fresh source analysis'}</span><Badge type="safe">ASSESSMENT READY</Badge></label><button className="primary" disabled={busy} onClick={()=>file?submit():document.getElementById('source-zip')?.click()}>{busy?<><span className="spinner"/>Analyzing source…</>:file?'Start source assessment':'Choose ZIP to run assessment'}</button></div>{error&&<div className="error-box">{error}</div>}<div className="assessment-run"><span>LAST RUN</span><b>{state.run?state.run.assessmentId:state.app.id}</b><span>{state.run?`${state.run.filesAnalyzed} files analyzed · ${state.run.findings.length} generated findings`:'Demo profile ready · worldmonitor-source-v1.2.zip · synthetic presentation state.'}</span>{state.run&&<button className="text" onClick={download}>Download report →</button>}</div></section><section className="panel"><h3>Static-analysis modules</h3><div className="module-grid">{['SSRF request flows','IDOR / authorization','Authentication context','Hardcoded secrets','Security configuration','Source evidence','Control detection','Risk confidence'].map((x,i)=><div key={x}><b>{x}</b><span>{i<5?'Focused rule executes against uploaded source':'Evidence-backed analysis output'}</span></div>)}</div></section></Page>}
function Risk(){const {state}=useStore();return <Page title="Risk analysis" desc="Prioritized World Monitor exposures from the simulated assessment profile." action={<Badge type="info">SIMULATED ASSESSMENT PROFILE</Badge>}><section className="panel">{state.findings.length?<div className="risk-table">{state.findings.slice().sort((a,b)=>sevOrder[a.severity]-sevOrder[b.severity]).map(f=><div key={f.id}><b>{f.id} · {f.title}</b><span>Severity <Badge type={f.severity}>{f.severity}</Badge></span><span>Confidence {f.confidence}%</span><strong>{f.severity==='high'?'P1':'P2'}</strong></div>)}</div>:<div className="empty-state"><h3>No risk scores available</h3><p>Upload a source archive to generate evidence-backed findings and risk priorities.</p></div>}</section></Page>}
function Reports(){const {state,dispatch}=useStore();const generated=!!state.run;const controls=[...new Set(state.findings.flatMap(f=>f.securityControls||f.controls||[]))];const summary=generated?`Static analysis completed for ${state.app.name}. ${state.run.filesAnalyzed} source files were analyzed with ${state.run.rulesExecuted.length} focused rules, generating ${state.findings.length} evidence-backed findings.`:'No source archive has been analyzed in this session. This report contains the current Sentry demo assessment profile.';const download=async()=>{const payload={application:state.app.name,title:`${state.app.name} Security Assessment`,assessmentId:state.app.id,generatedAt:new Date().toISOString(),scope:state.app.scope,filesAnalyzed:generated?state.run.filesAnalyzed:null,rulesExecuted:generated?state.run.rulesExecuted:null,summary,controlsConsidered:controls,findings:state.findings.map(f=>({id:f.id,title:f.title,status:f.status,severity:f.severity,confidence:f.confidence,file:f.file,line:f.line,recommendation:f.recommendation}))};try{await downloadReportPair(payload,`${state.app.id}-security-assessment`);dispatch({type:'TOAST',message:'Report downloaded'})}catch(e){alert(e.message)}};return <Page title="Security reports" desc="Report content is generated from the current assessment run." action={<button className="primary" onClick={download}>Export report</button>}><article className="report panel"><span className="eyebrow">ASSESSMENT REPORT · {state.app.id}</span><h1>{state.app.name} Security Assessment</h1><p>{state.app.scope}</p><hr/><h2>Executive summary</h2><p>{summary}</p>{generated&&<p><b>Files analyzed:</b> {state.run.filesAnalyzed} · <b>Rules executed:</b> {state.run.rulesExecuted.join(', ')}</p>}<h2>Security controls considered</h2>{controls.length?<ul>{controls.map(c=><li key={c}>{c}</li>)}</ul>:<p>No source-control records are available until an archive is assessed.</p>}<h2>Findings</h2>{state.findings.map(f=><p key={f.id}><Badge type={f.status==='NOT CONFIRMED'?'safe':'medium'}>{f.status}</Badge> <b>{f.title}</b> — {f.file||'case study'}{f.line?`:${f.line}`:''}; confidence {f.confidence}%.</p>)}</article></Page>}
const sourceFiles={};
function SourceViewer({setPage}){const {state}=useStore();const file=state.selectedSource||'No repository source loaded';const current=state.findings.find(f=>f.file===file)||state.findings.find(f=>f.id===state.selectedFinding);const code=current?.evidence||sourceFiles[file]||'No source evidence is available for this file.';return <Page title="Source-code evidence" desc="Read-only evidence view. Assessment interpretation is kept separate from source evidence." action={<button className="ghost" onClick={()=>setPage('detail')}>← Back to investigation</button>}><section className="panel source-view"><div className="panel-head"><div><span className="eyebrow">SOURCE CODE EVIDENCE</span><h3>{file}{current?.line?` · line ${current.line}`:''}</h3></div><Badge type="safe">INSPECTED</Badge></div><pre>{code}</pre><div className="source-interpretation"><span>ASSESSMENT INTERPRETATION</span><p>{current?.reason||'This excerpt represents the control relevant to the selected potential signal. The final result is not confirmed for the inspected path; it is not a claim about unreviewed application flows.'}</p></div></section></Page>}
function Settings(){const {state}=useStore();return <Page title="Assessment configuration" desc="Scope and guardrails for this authorized source-code review."><section className="panel settings"><h3>Target boundary</h3><label>Target application<input value={state.app.name} readOnly/></label><label>Assessment scope<input value={state.app.scope} readOnly/></label><label>Assessment mode<input value="Authorized source-code review · inspected flows only" readOnly/></label><div className="safe-box"><b>Scope guardrail enabled</b><span>Conclusions do not claim that the entire World Monitor application is secure.</span></div></section></Page>}
function ActivityLog(){const {state,dispatch}=useStore();const download=async(run)=>{try{await downloadReportPair(runToReportPayload(run),`${run.application}-${run.assessmentId}`);dispatch({type:'TOAST',message:'Report downloaded'})}catch(e){alert(e.message)}};return <Page title="Previous activities" desc="A history of assessment runs performed in this session, with generated reports available for download."><section className="panel">{state.activities.length?<div className="table-wrap"><table><thead><tr><th>Assessment</th><th>Date</th><th>Files analyzed</th><th>Findings</th><th></th></tr></thead><tbody>{state.activities.map(a=><tr key={a.id}><td><b>{a.id}</b><span>{a.application}</span></td><td>{new Date(a.timestamp).toLocaleString()}</td><td>{a.filesAnalyzed}</td><td>{a.findingsCount}</td><td><button className="ghost" onClick={()=>download(a.run)}>↓ Download report</button></td></tr>)}</tbody></table></div>:<p className="readable">No assessments have been run yet. Start a real assessment to see activity here.</p>}</section></Page>}
