function Login({onLogin}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[showPw,setShowPw]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[shake,setShake]=useState(false);const fail=msg=>{setError(msg);setShake(true);setTimeout(()=>setShake(false),400)};const submit=e=>{e.preventDefault();if(!email||!password)return fail('Enter your email and password to continue.');if(email!==DEMO_EMAIL||password!==DEMO_PASSWORD)return fail('Invalid credentials. Use the demo credentials below.');setError('');setBusy(true);setTimeout(()=>{setBusy(false);onLogin()},700)};const fillDemo=()=>{setEmail(DEMO_EMAIL);setPassword(DEMO_PASSWORD);setError('')};return <div className="login-screen"><div className="login-panel"><div className="login-form-wrap"><h1>Welcome back</h1><p className="login-sub">Sign in to continue to your security workspace.</p><form className={`login-form${shake?' shake':''}`} onSubmit={submit}><label>Email address<input type="email" placeholder="you@company.com" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username"/></label><label>Password<div className="pw-field"><input type={showPw?'text':'password'} placeholder="••••••••" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/><button type="button" className="pw-toggle" onClick={()=>setShowPw(s=>!s)}>{showPw?'Hide':'Show'}</button></div></label><div className="login-row"><label className="remember"><input type="checkbox"/> Remember me</label><a href="#" onClick={e=>e.preventDefault()}>Forgot password?</a></div>{error&&<div className="error-box">{error}</div>}<button className="primary login-submit" disabled={busy}>{busy?<><span className="spinner"/>Signing in…</>:'Sign in'}</button></form><div className="demo-credentials"><span>Demo credentials</span><div className="demo-credentials-row"><b>Email</b><code>{DEMO_EMAIL}</code></div><div className="demo-credentials-row"><b>Password</b><code>{DEMO_PASSWORD}</code></div><button type="button" className="text" onClick={fillDemo}>Autofill →</button></div><p className="login-footer">Authorized personnel only · Isolated local assessment environment</p></div></div><div className="login-visual"><div className="login-orb login-orb-1"/><div className="login-orb login-orb-2"/><div className="login-visual-inner"><div className="login-visual-brand"><Logo size={62}/><span>SENTRY</span></div><p className="login-tagline">Static analysis, evidence-backed, and safe by default.</p></div></div></div>}
function App(){const [state,dispatch]=useReducer(reducer,seed);const [page,setPage]=useState('overview');const [authed,setAuthed]=useState(false);if(!authed)return <><Login onLogin={()=>setAuthed(true)}/><div className="login-theme-toggle"><ThemeToggle/></div></>;const comp={overview:Overview,telemetry:Telemetry,isolation:({setPage})=><IsolationLab onBack={()=>setPage('telemetry')}/>,'remediation-workspace':RemediationWorkspace,compliance:ComplianceReport,assessment:Assessment,map:Map,graph:Graph,findings:Findings,detail:Detail,paths:Paths,risk:Risk,simulation:Simulation,remediation:Remediation,verification:Verification,reports:Reports,activity:ActivityLog,settings:Settings,source:SourceViewer}[page];const C=comp||Overview;return <Store.Provider value={{state,dispatch,setPage}}><div className="app"><Sidebar page={page} setPage={setPage} onLogout={()=>{setAuthed(false);setPage('overview')}}/><div className="content"><Topbar/>{page==='predictive'?<PredictiveForecast/>:page==='impact'?<BusinessImpact onBack={()=>setPage('overview')}/>:page==='telemetry'?<C setPage={setPage}/>:page==='remediation-workspace'?<C/>:<C setPage={setPage}/>}</div><Toast/></div></Store.Provider>}

class AppErrorBoundary extends React.Component {
  state = { error: null };
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { console.error('Sentry UI render error:', error, info.componentStack); }
  render() {
    if (!this.state.error) return this.props.children;
    return <main className="app-error-screen" role="alert">
      <span className="eyebrow">SENTRY · RECOVERY</span>
      <h1>The workspace hit a display error</h1>
      <p>Your sign-in completed, but part of the dashboard could not render.</p>
      <pre>{this.state.error.stack || this.state.error.message || String(this.state.error)}</pre>
      <button className="primary" onClick={() => window.location.reload()}>Reload workspace</button>
    </main>;
  }
}

createRoot(document.getElementById('root')).render(<AppErrorBoundary><App/></AppErrorBoundary>);
